class RAGContextFormatter(Component):
    display_name = "RAG Context Formatter (Cookie Strip Only)"
    description = "Formats PGVector list[Data] into readable context. Removes ONLY cookie banner text."
    icon = "braces"
    name = "rag_context_formatter_cookie_only"

    inputs = [
        HandleInput(
            name="results",
            display_name="Results (list[Data])",
            input_types=["Data"],  # PGVector returns list[Data] under Data handle
            required=True,
        ),
        BoolInput(
            name="strip_cookie_banner",
            display_name="Strip Cookie Banner",
            value=True,
            advanced=True,
        ),
        BoolInput(
            name="clean_empty_lines",
            display_name="Clean Empty Lines",
            value=True,
            advanced=True,
        ),
        MessageTextInput(
            name="chunk_separator",
            display_name="Chunk Separator",
            value="\n\n---\n\n",
            advanced=True,
        ),
        BoolInput(
            name="include_headers",
            display_name="Include [rank] source_url chunk_id score header",
            value=True,
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Context", name="context", method="build_context"),
    ]

    # -----------------------------
    # Extraction helpers
    # -----------------------------
    @staticmethod
    def _payload(item: Data) -> Dict[str, Any]:
        return item.data if isinstance(item.data, dict) else {}

    @staticmethod
    def _metadata(payload: Dict[str, Any]) -> Dict[str, Any]:
        md = payload.get("metadata")
        return md if isinstance(md, dict) else {}

    @staticmethod
    def _get_text(item: Data) -> str:
        payload = item.data if isinstance(item.data, dict) else {}
        # Most common shapes:
        # - payload["text"] (docs_to_data)
        # - payload["page_content"]
        if isinstance(payload.get("text"), str) and payload["text"].strip():
            return payload["text"]
        if isinstance(payload.get("page_content"), str) and payload["page_content"].strip():
            return payload["page_content"]

        # Fallback: if Data has its own text field (depends on LF version)
        t = getattr(item, "text", None)
        if isinstance(t, str) and t.strip():
            return t

        return ""

    @staticmethod
    def _get_score(payload: Dict[str, Any]) -> Optional[float]:
        # You stored it as _pgvector_score in your instrumented node
        s = payload.get("_pgvector_score")
        try:
            return float(s) if s is not None else None
        except Exception:
            return None

    @staticmethod
    def _get_source_url(payload: Dict[str, Any]) -> str:
        md = RAGContextFormatter._metadata(payload)

        for key in ("source_url", "source", "url"):
            v = md.get(key)
            if isinstance(v, str) and v.strip():
                return v.strip()

        for key in ("source_url", "source", "url"):
            v = payload.get(key)
            if isinstance(v, str) and v.strip():
                return v.strip()

        return ""

    @staticmethod
    def _get_chunk_id(payload: Dict[str, Any], rank: int) -> str:
        md = RAGContextFormatter._metadata(payload)

        for key in ("chunk_id", "custom_id", "uuid", "id", "doc_id"):
            v = md.get(key)
            if isinstance(v, str) and v.strip():
                return v.strip()

        for key in ("chunk_id", "custom_id", "uuid", "id", "doc_id"):
            v = payload.get(key)
            if isinstance(v, str) and v.strip():
                return v.strip()

        # fallback: stable enough for logging
        src = RAGContextFormatter._get_source_url(payload)
        return f"{src}::r{rank}" if src else f"rank_{rank}"

    # -----------------------------
    # Cookie stripping ONLY
    # -----------------------------
    @staticmethod
    def _strip_cookie_block(text: str) -> str:
        """
        Removes cookie-banner tail text, but does NOT dedupe and does NOT enforce max length.
        Strategy:
          - Find first occurrence of strong cookie markers.
          - Cut from that marker to end (cookie banner is almost always at the end).
        """
        if not text:
            return text

        lower = text.lower()

        # Strong markers that reliably indicate cookie banner start
        markers = [
            "we use cookies",
            "cookie settings",
            "accept all",
            "manage consent",
            "privacy overview",
            "consent to the use",
            "strictly necessary",
            "stored on your browser",
            "third-party cookies",
        ]

        positions = [lower.find(m) for m in markers if lower.find(m) != -1]
        if not positions:
            return text

        cut_at = min(positions)

        # Extra safety: only cut if the tail actually looks cookie-related
        tail = lower[cut_at : min(len(lower), cut_at + 600)]
        cookieish = any(k in tail for k in ("cookie", "consent", "privacy"))
        if not cookieish:
            return text

        return text[:cut_at].rstrip()

    @staticmethod
    def _clean_lines(text: str) -> str:
        # Just removes empty lines and trims right spaces; doesn't shrink content otherwise
        lines = [ln.rstrip() for ln in text.splitlines()]
        lines = [ln for ln in lines if ln.strip() != ""]
        return "\n".join(lines)

    def build_context(self) -> Message:
        r = self.results

        # Normalize to list[Data]
        items: List[Data] = []
        if isinstance(r, list):
            items = [x for x in r if isinstance(x, Data)]
        elif isinstance(r, Data):
            items = [r]

        if not items:
            return Message(text="")

        out_parts: List[str] = []
        for i, item in enumerate(items):
            rank = i + 1
            payload = self._payload(item)
            text = self._get_text(item)

            if self.strip_cookie_banner:
                text = self._strip_cookie_block(text)

            if self.clean_empty_lines:
                text = self._clean_lines(text)

            if self.include_headers:
                src = self._get_source_url(payload)
                cid = self._get_chunk_id(payload, rank)
                score = self._get_score(payload)
                score_s = f"{score:.6f}" if isinstance(score, float) else "None"

                header = f"[{rank}] source_url={src} chunk_id={cid} score={score_s}"
                out_parts.append(header)
                out_parts.append(text)
            else:
                out_parts.append(text)

        sep = self.chunk_separator or "\n\n---\n\n"
        final = sep.join(out_parts).strip()
        self.status = final
        return Message(text=final)

from __future__ import annotations

import datetime as dt
from typing import Any, Dict, List, Optional, Union

from langflow.custom.custom_component.component import Component
from langflow.io import BoolInput, HandleInput, MessageTextInput, Output
from langflow.schema.message import Message
from langflow.schema.data import Data


class ChatAPIPayloadOutput(Component):
    """
    Single-output API payload builder (grey output).

    Input:
      - user_text: the user's prompt (string)
      - assistant: Message or string (assistant answer)
      - generation: dict from Ollama envelope node: {text, metrics, raw}
      - retrieval: dict from PGVector extractor: {metrics, chunks}

    Output:
      - payload: dict you can return to website via LangFlow flow endpoint
    """

    display_name = "Chat Output (API Payload)"
    description = "Builds one JSON payload: {user, assistant, metrics, retrieval_chunks,...} for your website backend."
    icon = "cloud-upload"
    name = "chat_api_payload_output"

    inputs = [
        MessageTextInput(
            name="user_text",
            display_name="User Text",
            info="Raw user prompt text (what the user typed).",
            required=True,
        ),
        HandleInput(
            name="assistant",
            display_name="Assistant (Message or Text)",
            input_types=["Message", "Data"],  # accept Message; Data for safety; also works with raw text
            required=True,
        ),
        HandleInput(
            name="generation",
            display_name="Generation Envelope (dict)",
            input_types=["Data"],  # LangFlow will pass dict-like through the handle system
            required=False,
        ),
        HandleInput(
            name="retrieval",
            display_name="Retrieval Envelope (dict)",
            input_types=["Data"],
            required=False,
        ),
        BoolInput(
            name="include_retrieval_chunks",
            display_name="Include Retrieval Chunks",
            value=True,
            advanced=True,
        ),
        BoolInput(
            name="include_generation_raw",
            display_name="Include Ollama Raw JSON",
            value=False,
            advanced=True,
        ),
    ]

    outputs = [
        Output(display_name="Payload", name="payload", method="build_payload"),
    ]

    # -----------------------
    # Helpers
    # -----------------------
    @staticmethod
    def _now_utc_iso() -> str:
        return dt.datetime.now(dt.timezone.utc).isoformat()

    @staticmethod
    def _as_dict(x: Any) -> Optional[Dict[str, Any]]:
        # Accept dict directly
        if isinstance(x, dict):
            return x
        # Accept Data(data={...})
        if isinstance(x, Data) and isinstance(x.data, dict):
            return x.data
        # Some LF versions wrap dict-ish objects; try best-effort
        try:
            if hasattr(x, "data") and isinstance(getattr(x, "data"), dict):
                return getattr(x, "data")
        except Exception:
            pass
        return None

    @staticmethod
    def _assistant_text(assistant: Any) -> str:
        if isinstance(assistant, Message):
            return assistant.text or ""
        if isinstance(assistant, str):
            return assistant
        # Sometimes Message serialized into dict-like
        if isinstance(assistant, dict):
            t = assistant.get("text")
            return t if isinstance(t, str) else ""
        if isinstance(assistant, Data) and isinstance(assistant.data, dict):
            # try common keys
            for k in ("text", "content", "message"):
                v = assistant.data.get(k)
                if isinstance(v, str):
                    return v
        # last resort
        return str(assistant)

    @staticmethod
    def _safe_pick_metrics(gen_env: Dict[str, Any]) -> Dict[str, Any]:
        m = gen_env.get("metrics")
        return m if isinstance(m, dict) else {}

    @staticmethod
    def _safe_pick_retrieval_metrics(ret_env: Dict[str, Any]) -> Dict[str, Any]:
        m = ret_env.get("metrics")
        return m if isinstance(m, dict) else {}

    @staticmethod
    def _safe_pick_chunks(ret_env: Dict[str, Any]) -> List[Dict[str, Any]]:
        c = ret_env.get("chunks")
        return c if isinstance(c, list) else []

    # -----------------------
    # Core
    # -----------------------
    def build_payload(self) -> Dict[str, Any]:
        assistant_text = self._assistant_text(self.assistant)

        gen_env = self._as_dict(self.generation) or {}
        ret_env = self._as_dict(self.retrieval) or {}

        gen_metrics = self._safe_pick_metrics(gen_env)
        ret_metrics = self._safe_pick_retrieval_metrics(ret_env)

        payload: Dict[str, Any] = {
            "timestamp_utc": self._now_utc_iso(),
            "user_text": self.user_text or "",
            "assistant_text": assistant_text,
            "metrics": {
                "generation": gen_metrics,
                "retrieval": ret_metrics,
            },
        }

        if self.include_retrieval_chunks:
            payload["retrieval_chunks"] = self._safe_pick_chunks(ret_env)

        if self.include_generation_raw:
            raw = gen_env.get("raw")
            payload["generation_raw"] = raw if isinstance(raw, dict) else raw

        # Convenience: promote a few common fields (optional)
        if isinstance(gen_metrics.get("model"), str):
            payload["model"] = gen_metrics["model"]

        return payload
